/**
 * @see https://websockets.spec.whatwg.org/#feedback-from-the-protocol
 */
#onConnectionEstablished (response, parsedExtensions) {
  // processResponse is called when the "response's header list has been received and initialized."
  // once this happens, the connection is open
  this.#handler.socket = response.socket

  // Get options from dispatcher options
  const maxFragments = this.#handler.controller.dispatcher?.webSocketOptions?.maxFragments
  const maxPayloadSize = this.#handler.controller.dispatcher?.webSocketOptions?.maxPayloadSize

  const parser = new ByteParser(this.#handler, parsedExtensions, {
    maxFragments,
    maxPayloadSize
  })
  parser.on('drain', () => this.#handler.onParserDrain())
  parser.on('error', (err) => this.#handler.onParserError(err))

  this.#parser = parser
  this.#sendQueue = new SendQueue(response.socket)

  // 1. Change the ready state to OPEN (1).
  this.#handler.readyState = states.OPEN

  // 2. Change the extensions attribute’s value to the extensions in use, if
  //    it is not the null value.
  // https://datatracker.ietf.org/doc/html/rfc6455#section-9.1
  const extensions = response.headersList.get('sec-websocket-extensions')

  if (extensions !== null) {
    this.#extensions = extensions

  if (!this.#handler.closeState.has(sentCloseFrameState.SENT) && !this.#handler.closeState.has(sentCloseFrameState.RECEIVED)) {
    const frame = new WebsocketFrameSend(data)

    this.#handler.socket.write(frame.createFrame(opcode), () => {
      promise.resolve(undefined)
    })
  }

  // 6.3. Queue a global task on the WebSocket task source given stream ’s relevant global object to resolve promise with undefined.
  return promise.promise
}

/** @type {import('../websocket').Handler['onConnectionEstablished']} */
#onConnectionEstablished (response, parsedExtensions) {
  this.#handler.socket = response.socket

  const parser = new ByteParser(this.#handler, parsedExtensions)
  parser.on('drain', () => this.#handler.onParserDrain())
  parser.on('error', (err) => this.#handler.onParserError(err))

  this.#parser = parser

  // 1. Change stream ’s ready state to OPEN (1).
  this.#handler.readyState = states.OPEN

  // 2. Set stream ’s was ever connected to true.
  // This is done in the opening handshake.

  // 3. Let extensions be the extensions in use .
  const extensions = parsedExtensions ?? ''

'use strict'

const { test, after } = require('node:test')
const { WebSocketServer } = require('ws')
const { Agent, WebSocket } = require('../..')
const diagnosticsChannel = require('node:diagnostics_channel')

test('Fragmented frame with a ping frame in the middle of it', (t) => {
  const server = new WebSocketServer({ port: 0 })

  server.on('connection', (ws) => {
    const socket = ws._socket

    socket.write(Buffer.from([0x01, 0x03, 0x48, 0x65, 0x6c])) // Text frame "Hel"
    socket.write(Buffer.from([0x89, 0x05, 0x48, 0x65, 0x6c, 0x6c, 0x6f])) // ping "Hello"
    socket.write(Buffer.from([0x80, 0x02, 0x6c, 0x6f])) // Text frame "lo"
  })

  after(() => {
    for (const client of server.clients) {
      client.close()
    }

    server.close()
  })

  const ws = new WebSocket(`ws://localhost:${server.address().port}`)

  diagnosticsChannel.channel('undici:websocket:ping').subscribe(
    ({ payload }) => t.assert.deepStrictEqual(payload, Buffer.from('Hello'))
  )

  return new Promise((resolve) => {
    ws.addEventListener('message', ({ data }) => {
      t.assert.strictEqual(data, 'Hello')

      ws.close()
      resolve()
    })
  })
})

test('Too many fragments (uncompressed)', (t, done) => {
  t.plan(4)

  const agent = new Agent({
    webSocket: {
      maxFragments: 3
    }
  })

  const server = new WebSocketServer({ port: 0 }, () => {
    const { port } = server.address()
    const client = new WebSocket(`ws://127.0.0.1:${port}`, {
      dispatcher: agent
    })

    client.addEventListener('error', (event) => {
      t.assert.ok(true)
    })

    client.addEventListener('close', (event) => {
      t.assert.deepStrictEqual(event.code, 1006)
    })
  })

  server.on('connection', (ws) => {
    ws.on('close', (code, reason) => {
      t.assert.deepStrictEqual(code, 1008)
      t.assert.deepStrictEqual(reason.toString(), 'Too many message fragments')
      agent.close()
      server.close(done)
    })

    const fragment = Buffer.from('a')
    const options = { fin: false }

    ws.send(fragment, options)
    ws.send(fragment, options)
    ws.send(fragment, options)
    ws.send(fragment, options)
  })
})

test('Too many fragments (compressed)', (t, done) => {
  t.plan(4)

  const agent = new Agent({
    webSocket: {
      maxFragments: 3
    }
  })

  const server = new WebSocketServer({
    perMessageDeflate: { threshold: 0 },
    port: 0
  }, () => {
    const { port } = server.address()
    const client = new WebSocket(`ws://127.0.0.1:${port}`, {
      dispatcher: agent
    })

    client.addEventListener('error', (event) => {
      t.assert.ok(true)
    })

    client.addEventListener('close', (event) => {
      t.assert.deepStrictEqual(event.code, 1006)
    })
  })

  server.on('connection', (ws) => {
    ws.on('close', (code, reason) => {
      t.assert.deepStrictEqual(code, 1008)
      t.assert.deepStrictEqual(reason.toString(), 'Too many message fragments')
      agent.close()
      server.close(done)
    })

    const fragment = Buffer.from('a')
    const options = { fin: false }

    ws.send(fragment, options)
    ws.send(fragment, options)
    ws.send(fragment, options)
    ws.send(fragment, options)
  })
})

'use strict'

const { createInflateRaw, Z_DEFAULT_WINDOWBITS } = require('node:zlib')
const { isValidClientWindowBits } = require('./util')
const { MessageSizeExceededError } = require('../../core/errors')

const tail = Buffer.from([0x00, 0x00, 0xff, 0xff])
const kBuffer = Symbol('kBuffer')
const kLength = Symbol('kLength')

class PerMessageDeflate {
  /** @type {import('node:zlib').InflateRaw} */
  #inflate

  #options = {}

  #maxPayloadSize = 0

  /**
   * @param {Map<string, string>} extensions
   */
  constructor (extensions, options) {
    this.#options.serverNoContextTakeover = extensions.has('server_no_context_takeover')
    this.#options.serverMaxWindowBits = extensions.get('server_max_window_bits')

    this.#maxPayloadSize = options.maxPayloadSize
  }

  /**
   * Decompress a compressed payload.
   * @param {Buffer} chunk Compressed data
   * @param {boolean} fin Final fragment flag
   * @param {Function} callback Callback function
   */
  decompress (chunk, fin, callback) {
    // An endpoint uses the following algorithm to decompress a message.
    // 1.  Append 4 octets of 0x00 0x00 0xff 0xff to the tail end of the
    //     payload of the message.
    // 2.  Decompress the resulting data using DEFLATE.
    if (!this.#inflate) {
      let windowBits = Z_DEFAULT_WINDOWBITS

      if (this.#options.serverMaxWindowBits) { // empty values default to Z_DEFAULT_WINDOWBITS
        if (!isValidClientWindowBits(this.#options.serverMaxWindowBits)) {
          callback(new Error('Invalid server_max_window_bits'))
          return
        }

        windowBits = Number.parseInt(this.#options.serverMaxWindowBits)
      }

      try {
        this.#inflate = createInflateRaw({ windowBits })
      } catch (err) {
        callback(err)
        return
      }
      this.#inflate[kBuffer] = []
      this.#inflate[kLength] = 0

      this.#inflate.on('data', (data) => {
        this.#inflate[kLength] += data.length

        if (this.#maxPayloadSize > 0 && this.#inflate[kLength] > this.#maxPayloadSize) {
          callback(new MessageSizeExceededError())
          this.#inflate.removeAllListeners()
          this.#inflate = null
          return
        }

        this.#inflate[kBuffer].push(data)
      })

      this.#inflate.on('error', (err) => {
        this.#inflate = null
        callback(err)
      })
    }

    this.#inflate.write(chunk)
    if (fin) {
      this.#inflate.write(tail)
    }

    this.#inflate.flush(() => {
      if (!this.#inflate) {
        return
      }

      const full = Buffer.concat(this.#inflate[kBuffer], this.#inflate[kLength])

      this.#inflate[kBuffer].length = 0
      this.#inflate[kLength] = 0

      callback(null, full)
    })
  }
}

module.exports = { PerMessageDeflate }

