'use strict'

const { test } = require('node:test')
const { once } = require('node:events')
const { WebSocketServer } = require('ws')
const {
  Agent,
  WebSocketStream,
  getGlobalDispatcher,
  setGlobalDispatcher
} = require('../../..')

// WebSocketStream has no `dispatcher` option, so the limits are read from the
// global dispatcher.
test('WebSocketStream honors the dispatcher\'s maxFragments option', async (t) => {
  const server = new WebSocketServer({ port: 0 })
  const agent = new Agent({
    webSocket: {
      maxFragments: 3
    }
  })
  const previousDispatcher = getGlobalDispatcher()

  setGlobalDispatcher(agent)

  t.after(async () => {
    setGlobalDispatcher(previousDispatcher)
    await agent.close()
    server.close()
  })

  await once(server, 'listening')

  const connection = new Promise((resolve) => {
    server.on('connection', (ws) => {
      const fragment = Buffer.from('a')
      const options = { fin: false }

      ws.send(fragment, options)
      ws.send(fragment, options)
      ws.send(fragment, options)
      ws.send(fragment, options)

      resolve(ws)
    })
  })

  const wss = new WebSocketStream(`ws://127.0.0.1:${server.address().port}`)
  // Swallow the expected unclean-close rejection on the client side.
  wss.closed.catch(() => {})

  await wss.opened

  const ws = await connection
  const [code, reason] = await once(ws, 'close')

  t.assert.strictEqual(code, 1008)
  t.assert.strictEqual(reason.toString(), 'Too many message fragments')
})

